import{_ as s,C as i,o as a,c as r,a2 as n,b as l,w as t,a as c,E as d,a3 as g}from"./chunks/framework.Dd_iHz3e.js";const v=JSON.parse('{"title":"14.4 Load Balancing & Horizontal Scaling","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.4-load-balancing-and-scaling.md","filePath":"system-design/14.4-load-balancing-and-scaling.md"}'),h={name:"system-design/14.4-load-balancing-and-scaling.md"};function u(p,e,m,b,f,_){const o=i("Mermaid");return a(),r("div",null,[e[1]||(e[1]=n('<h1 id="_14-4-load-balancing-horizontal-scaling" tabindex="-1">14.4 Load Balancing &amp; Horizontal Scaling <a class="header-anchor" href="#_14-4-load-balancing-horizontal-scaling" aria-label="Permalink to &quot;14.4 Load Balancing &amp; Horizontal Scaling&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>Load balancing distributes incoming client requests across a pool of backend servers to ensure no single server becomes overwhelmed, enabling horizontal scaling (adding more instances) and high availability.</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li>The Express backend is designed as a <strong>Stateless Application</strong>. User authentication state is encapsulated entirely within signed JSON Web Tokens ([controllers/authController.js](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/controllers/authController.js)), meaning any server instance can handle any incoming request without requiring sticky sessions.</li><li>In production, a Layer 7 Application Load Balancer (ALB) terminates TLS and routes traffic across backend Docker containers.</li></ul><hr><h2 id="_3-load-balancing-topology" tabindex="-1">3. Load Balancing Topology <a class="header-anchor" href="#_3-load-balancing-topology" aria-label="Permalink to &quot;3. Load Balancing Topology&quot;">​</a></h2>',8)),(a(),l(g,null,{default:t(()=>[d(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Clients%5B%22Client%20Devices%20%26%20IoT%20Cameras%22%5D%20--%3E%20DNS%5B%22Route%2053%20%2F%20Cloudflare%20DNS%22%5D%0A%20%20%20%20DNS%20--%3E%20ALB%5B%22Layer%207%20Application%20Load%20Balancer%22%5D%0A%20%20%20%20ALB%20--%3E%7CRound%20Robin%20%2F%20Least%20Connections%7C%20Pod1%5B%22Express%20Instance%201%20(Port%205000)%22%5D%0A%20%20%20%20ALB%20--%3E%7CRound%20Robin%20%2F%20Least%20Connections%7C%20Pod2%5B%22Express%20Instance%202%20(Port%205000)%22%5D%0A%20%20%20%20ALB%20--%3E%7CRound%20Robin%20%2F%20Least%20Connections%7C%20Pod3%5B%22Express%20Instance%203%20(Port%205000)%22%5D%0A%20%20%20%20Pod1%20%26%20Pod2%20%26%20Pod3%20--%3E%20MongoPrimary%5B(%22MongoDB%20Replica%20Set%22)%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<hr><h2 id="_4-load-balancing-algorithms-comparison" tabindex="-1">4. Load Balancing Algorithms Comparison <a class="header-anchor" href="#_4-load-balancing-algorithms-comparison" aria-label="Permalink to &quot;4. Load Balancing Algorithms Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Algorithm</th><th>Mechanism</th><th>Pros</th><th>Cons</th><th>Fit for Cooking Nexus</th></tr></thead><tbody><tr><td><strong>Round Robin (Chosen default)</strong></td><td>Cycles sequentially through server list</td><td>Simple, zero overhead</td><td>Ignores server CPU load</td><td>Excellent for stateless pings</td></tr><tr><td><strong>Least Connections (Recommended)</strong></td><td>Routes to server with fewest open TCP sockets</td><td>Prevents overload on heavy tasks</td><td>Requires central state tracking</td><td>Best for mixed telemetry/heavy routes</td></tr><tr><td><strong>IP Hash (Sticky)</strong></td><td>Hashes client IP to select server</td><td>Retains local in-memory caches</td><td>Uneven load distribution</td><td>Anti-pattern for stateless APIs</td></tr><tr><td><strong>Layer 4 (Transport/TCP)</strong></td><td>Routes based on IP and port only</td><td>Ultra-fast (microsecond latency)</td><td>Cannot inspect HTTP paths or headers</td><td>Good for raw MQTT, bad for REST</td></tr><tr><td><strong>Layer 7 (Application/HTTP)</strong></td><td>Inspects URL, headers, and cookies</td><td>Intelligent path-based routing</td><td>Slight CPU parsing overhead</td><td>Optimal for routing <code>/api/*</code> vs <code>/cdn/*</code></td></tr></tbody></table><hr><h2 id="_5-trade-offs-accepted" tabindex="-1">5. Trade-offs Accepted <a class="header-anchor" href="#_5-trade-offs-accepted" aria-label="Permalink to &quot;5. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>Stateless vs Local Caching</strong>: Keeping backend nodes completely stateless means we cannot cache user profiles in local Node.js process memory without risk of stale cache across instances, requiring a central Redis cache.</li></ul><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: ALB health checks fail if a single long-running query blocks the Node.js event loop on one instance.</li><li><strong>At 100x</strong>: Database connection exhaustion: 50 horizontally scaled Express instances opening 20 Mongoose connections each = 1,000 open connections to MongoDB, reaching Atlas connection caps.</li><li><strong>At 1,000x</strong>: Single cloud region ALB failure: an AWS us-east-1 outage takes down all backend instances simultaneously.</li></ul><hr><h2 id="_7-senior-engineer-improvements" tabindex="-1">7. Senior Engineer Improvements <a class="header-anchor" href="#_7-senior-engineer-improvements" aria-label="Permalink to &quot;7. Senior Engineer Improvements&quot;">​</a></h2><ol><li>Implement a dedicated <code>/health</code> endpoint that checks database ping without executing heavy queries.</li><li>Introduce a <strong>Connection Pooling Proxy</strong> (like AWS DocumentDB elastic clusters or MongoDB connection pooling sidecars) to multiplex database connections.</li><li>Configure <strong>Multi-Region Active-Active Failover</strong> with Route 53 latency routing.</li></ol><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;Because our Express backend is completely stateless and uses self-contained JWT tokens for authentication, we can scale horizontally behind a Layer 7 Application Load Balancer using a Least Connections algorithm. Any instance can process an incoming <code>/api/vision</code> frame or verify a magic login token without requiring sticky sessions. As we scale out instances, we guard our database connection limit using connection pool caps in Mongoose to prevent replica set saturation.&quot;</p>',15))])}const A=s(h,[["render",u]]);export{v as __pageData,A as default};
